export default function About() {
  return (
    <section className="section">
      <h2 className="section-title">About Me</h2>

      <div className="about-card">
        <p>
          I am a passionate Computer Science student interested in React,
          Node.js, Artificial Intelligence, and full stack development.
        </p>
      </div>
    </section>
  );
}
